export const EP36_SCENES = [
  {id: "hook", title: "同一 Driver，改变的是哪一层", duration: seconds(23), captions: [{"from":3.25,"to":8.857,"text":"特殊文件不容易直接阅读、合并或规范化时，Git 可以把路径交给自定义 driver"},{"from":9.58,"to":13.581,"text":"但 diff driver、merge driver 和 clean / smudge filter 改变的并不是同一层"},{"from":14.322,"to":17.658,"text":"如果把它们都理解成“转换文件”，就会误判 blob 是否真的变化"},{"from":18.381,"to":20.961,"text":"我们用同一种 demo 格式，做三次隔离实验"}]},
  {id: "driver-model", title: "Attributes 选路，Config 提供命令", duration: seconds(23.5), captions: [{"from":3.25,"to":6.882,"text":".gitattributes 负责说 data.demo 使用哪个 driver 名称"},{"from":7.599,"to":10.025,"text":"真正执行的命令通常来自 Git config"},{"from":10.659,"to":16.067,"text":"因此 clone 可以带来 path rule，却不会自动替当前机器安装脚本或配置 driver"},{"from":16.723,"to":21.488,"text":"这条部署边界很重要：规则可以共享，执行环境仍需要显式准备"}]},
  {id: "diff-driver", title: "Diff Driver 只改变阅读视图", duration: seconds(23), captions: [{"from":3.25,"to":5.151,"text":"第一条路径是 diff driver"},{"from":5.823,"to":11.066,"text":"Git 先读取 blob，再用 textconv 脚本生成更适合人比较的临时视图"},{"from":11.781,"to":16.749,"text":"启用前后，diff 的可读性明显不同，但 Index 里的 blob 对象 ID 没有改变"},{"from":17.515,"to":21.119,"text":"所以 textconv 服务审查，它不是写入仓库的内容转换"}]},
  {id: "merge-driver", title: "Merge Driver 写回合并结果", duration: seconds(26), captions: [{"from":3.25,"to":5.067,"text":"第二条路径是 merge driver"},{"from":5.688,"to":12.066,"text":"Git 把 base、当前一侧和另一侧的临时文件分别传入 %O、%A 与 %B"},{"from":12.709,"to":18.7,"text":"driver 需要把结果写回 %A，并用零退出码表示成功；非零则让 Git 保持冲突状态"},{"from":19.38,"to":24.256,"text":"这里的输出会参与后续提交，因此它和只读的 textconv 完全不同"}]},
  {id: "clean-smudge", title: "Filter 位于工作区与 Index 之间", duration: seconds(26.5), captions: [{"from":3.25,"to":5.842,"text":"第三条路径是 clean 和 smudge filter"},{"from":6.54,"to":11.312,"text":"clean 在内容进入 Index 前执行，smudge 在 checkout 到工作区时执行"},{"from":12.083,"to":16.314,"text":"我们让工作区保留便于编辑的前缀，而 Index 中只保存规范数据"},{"from":17.022,"to":20.999,"text":"再次 add 不应持续产生变化，因此示例 filter 必须幂等"},{"from":21.67,"to":24.645,"text":"它能改变 blob，却不是天然的加密或安全边界"}]},
  {id: "takeaway", title: "先确认输入、输出与失败语义", duration: seconds(28), captions: [{"from":3.25,"to":6.872,"text":"选择自定义 driver 时，可以先核对输入、输出和失败语义"},{"from":7.576,"to":15.327,"text":"diff driver 生成阅读视图，不改 blob。merge driver 写回合并结果，并用退出码表达成功或冲突"},{"from":15.956,"to":20.177,"text":"filter 位于工作区与 Index 之间，可能改变实际存储内容"},{"from":20.847,"to":25.86,"text":"attributes 只是选中名称，config 和脚本部署仍需要每台机器明确完成"}]},
] as const;
